$rows=json_decode(file_get_contents('/srv/state/cierre-38-20261104/reasons-dev1.json'),true,512,JSON_THROW_ON_ERROR);if(count($rows)!==38)throw new RuntimeException('Unexpected count');$p=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$p->beginTransaction();$find=$p->prepare('SELECT id FROM destinations WHERE slug=?');$get=$p->prepare('SELECT id FROM destination_reasons WHERE destination_id=? ORDER BY display_order,id');$insert=$p->prepare('INSERT INTO destination_reasons(destination_id,display_order) VALUES(?,?)');$tr=$p->prepare('INSERT INTO destination_reason_translations(reason_id,locale,body) VALUES(?,?,?) ON DUPLICATE KEY UPDATE body=VALUES(body)');$out=[];
